import type { ReactNode } from "react";

/** Internal layout shared by domain panels. Shipped with its owning component. */
export function PanelHeader({
  icon,
  title,
  description,
  status,
  action,
  as: Heading = "h3",
}: {
  icon: ReactNode;
  title: string;
  description?: ReactNode;
  status?: ReactNode;
  action?: ReactNode;
  as?: "h2" | "h3";
}) {
  return (
    <div data-slot="panel-header" className="min-w-0">
      <div
        data-slot="panel-topline"
        className="grid min-w-0 grid-cols-[minmax(0,1fr)_auto] items-start gap-x-3 gap-y-2"
      >
        <div
          data-slot="panel-identity"
          className="flex min-w-0 items-start gap-3"
        >
          <span
            data-slot="panel-icon"
            aria-hidden="true"
            className="surface-control grid size-10 shrink-0 place-items-center rounded-full border bg-secondary text-secondary-foreground shadow-sm [&>svg]:size-4"
          >
            {icon}
          </span>
          <div
            data-slot="panel-heading"
            className="flex min-h-12 min-w-0 flex-col"
          >
            <Heading
              data-slot="panel-title"
              className="text-base font-medium leading-snug wrap-anywhere"
            >
              {title}
            </Heading>
            {description && (
              <p
                data-slot="panel-description"
                className="mt-1 text-sm leading-relaxed text-muted-foreground wrap-anywhere"
              >
                {description}
              </p>
            )}
          </div>
        </div>
        {(status != null || action != null) && (
          <div
            data-slot="panel-meta"
            className="ml-auto flex min-w-0 flex-wrap items-center justify-end gap-2 text-right text-sm text-muted-foreground"
          >
            {status != null && (
              <div data-slot="panel-status" className="min-w-0 wrap-anywhere">
                {status}
              </div>
            )}
            {action}
          </div>
        )}
      </div>
    </div>
  );
}

import type { ComponentProps } from "react";
import { PanelHeader } from "@/components/iot/internal/panel-header";

type PanelProps = ComponentProps<typeof PanelHeader> &
  Omit<ComponentProps<"section">, "title"> & {
    contentClassName?: string;
  };

/** Owns the surface, all four insets, header alignment and the content boundary. */
export function Panel({
  icon,
  title,
  description,
  status,
  action,
  as,
  className = "",
  contentClassName = "",
  children,
  ...props
}: PanelProps) {
  return (
    <section
      data-slot="panel"
      data-panel-layout=""
      className={`@container surface-raised grid min-w-0 gap-[var(--card-padding,24px)] rounded-xl border bg-card p-[var(--card-padding,24px)] text-card-foreground shadow-sm ${className}`}
      {...props}
    >
      <PanelHeader
        icon={icon}
        title={title}
        description={description}
        status={status}
        action={action}
        as={as}
      />
      <div
        data-slot="panel-content"
        className={`min-w-0 ${contentClassName || "space-y-5"}`}
      >
        {children}
      </div>
    </section>
  );
}

"use client";

import { Panel } from "@/components/iot/internal/panel";
import { useRef, useState } from "react";
import { Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";

export function AutomationNote({
  title,
  reason,
  source,
  time,
  status = "proposed",
  onAccept,
  onDismiss,
  disabled = false,
}: {
  title: string;
  reason: string;
  source: string;
  time: string;
  status?: "proposed" | "accepted" | "dismissed";
  disabled?: boolean;
  onAccept: () => Promise<void>;
  onDismiss: () => Promise<void>;
}) {
  const busy = useRef(false);
  const [pending, setPending] = useState<"accept" | "dismiss" | null>(null);
  const [error, setError] = useState("");
  async function act(action: "accept" | "dismiss") {
    if (busy.current || disabled || status !== "proposed") return;
    busy.current = true;
    setPending(action);
    setError("");
    try {
      await (action === "accept" ? onAccept() : onDismiss());
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "操作失败，请重试。");
    } finally {
      busy.current = false;
      setPending(null);
    }
  }
  return (
    <Panel
      icon={<Sparkles />}
      title={title}
      description="AI 建议"
      status={
        { proposed: "待人决策", accepted: "已采纳", dismissed: "已忽略" }[
          status
        ]
      }
    >
      <p className="text-sm text-muted-foreground tabular-nums">
        生成时间 · {time}
      </p>
      <p className="text-sm leading-relaxed text-muted-foreground">{reason}</p>
      <p className="text-xs text-muted-foreground">依据：{source}</p>
      <div aria-live="polite">
        {status === "proposed" ? (
          <div className="flex flex-wrap justify-end gap-2">
            <Button
              variant="ghost"
              className="min-h-10"
              disabled={disabled || pending !== null}
              onClick={() => act("dismiss")}
            >
              {pending === "dismiss" ? "处理中…" : "忽略"}
            </Button>
            <Button
              className="min-h-10"
              disabled={disabled || pending !== null}
              onClick={() => act("accept")}
            >
              {pending === "accept" ? "等待确认…" : "采纳建议"}
            </Button>
          </div>
        ) : (
          <p className="text-xs text-muted-foreground">
            {status === "accepted"
              ? "建议已采纳，执行进度请查看命令回执。"
              : "建议已忽略，设备保持原有设定。"}
          </p>
        )}
      </div>
      {error && (
        <p role="alert" className="text-xs text-destructive">
          {error}
        </p>
      )}
    </Panel>
  );
}
